        {
            dst.m_data.m_value = src.m_data.m_value.number_unsigned;
            break;
        }

        case value_t::number_float:
        {
            dst.m_data.m_value = src.m_data.m_value.number_float;
            break;
        }

        case value_t::object:
        case value_t::array:
        case value_t::null:
        case value_t::discarded:
        default:
            break;
    }
