bool get_cbor_binary_chunk(binary_t& result)
{
    switch (current)
    {
        // Binary data (0x00..0x17 bytes follow)
        case 0x40:
        case 0x41:
        case 0x42:
        case 0x43:
        case 0x44:
        case 0x45:
        case 0x46:
        case 0x47:
        case 0x48:
        case 0x49:
        case 0x4A:
        case 0x4B:
        case 0x4C:
        case 0x4D:
        case 0x4E:
        case 0x4F:
        case 0x50:
        case 0x51:
        case 0x52:
        case 0x53:
        case 0x54:
        case 0x55:
        case 0x56:
        case 0x57:
        {
            return get_binary(static_cast<unsigned int>(current) & 0x1Fu, result);
        }

        case 0x58: // Binary data (one-byte uint8_t for n follows)
        {
            std::uint8_t len{};
            return get_number(len) &&
                   get_binary(len, result);
        }

        case 0x59: // Binary data (two-byte uint16_t for n follow)
        {
            std::uint16_t len{};
            return get_number(len) &&
                   get_binary(len, result);
        }

        case 0x5A: // Binary data (four-byte uint32_t for n follow)
        {
            std::uint32_t len{};
            return get_number(len) &&
                   get_binary(len, result);
        }

        case 0x5B: // Binary data (eight-byte uint64_t for n follow)
        {
            std::uint64_t len{};
            return get_number(len) &&
                   get_binary(len, result);
        }

        default:
        {
            auto last_token = get_token_string();
            return sax->parse_error(chars_read, last_token, parse_error::create(113, chars_read,
                                    exception_message(concat("expected length specification (0x40-0x5B) or indefinite binary array type (0x5F); last byte: 0x", last_token), "binary"), nullptr));
        }
    }
}
