bool get_msgpack_string(string_t& result, const char* context = "string")
{
    if (JSON_HEDLEY_UNLIKELY(!unexpect_eof("string")))
    {
        return false;
    }

    switch (current)
    {
        // fixstr
        case 0xA0:
        case 0xA1:
        case 0xA2:
        case 0xA3:
        case 0xA4:
        case 0xA5:
        case 0xA6:
        case 0xA7:
        case 0xA8:
        case 0xA9:
        case 0xAA:
        case 0xAB:
        case 0xAC:
        case 0xAD:
        case 0xAE:
        case 0xAF:
        case 0xB0:
        case 0xB1:
        case 0xB2:
        case 0xB3:
        case 0xB4:
        case 0xB5:
        case 0xB6:
        case 0xB7:
        case 0xB8:
        case 0xB9:
        case 0xBA:
        case 0xBB:
        case 0xBC:
        case 0xBD:
        case 0xBE:
        case 0xBF:
        {
            return get_string(static_cast<unsigned int>(current) & 0x1Fu, result) && check_string_utf8(result, context);
        }

        case 0xD9: // str 8
        {
            std::uint8_t len{};
            return get_number(len) && get_string(len, result) && check_string_utf8(result, context);
        }

        case 0xDA: // str 16
        {
            std::uint16_t len{};
            return get_number(len) && get_string(len, result) && check_string_utf8(result, context);
        }

        case 0xDB: // str 32
        {
            std::uint32_t len{};
            return get_number(len) && get_string(len, result) && check_string_utf8(result, context);
        }

        default:
        {
            auto last_token = get_token_string();
            return sax->parse_error(chars_read, last_token, parse_error::create(113, chars_read,
                                    exception_message(concat("expected length specification (0xA0-0xBF, 0xD9-0xDB); last byte: 0x", last_token), "string"), nullptr));
        }
    }
}
