fn all_placeholders() {
    use Token::*;

    let templ = FormatTemplate::parse(
        "{{path={} \
        basename={/} \
        parent={//} \
        noExt={.} \
        basenameNoExt={/.} \
        }}",
    );
    assert_eq!(
        templ,
        FormatTemplate::Tokens(vec![
            Text("{path=".into()),
            Placeholder,
            Text(" basename=".into()),
            Basename,
            Text(" parent=".into()),
            Parent,
            Text(" noExt=".into()),
            NoExt,
            Text(" basenameNoExt=".into()),
            BasenameNoExt,
            Text(" }".into()),
        ])
    );

    let mut path = PathBuf::new();
    path.push("a");
    path.push("folder");
    path.push("file.txt");

    let expanded = templ.generate(&path, Some("/")).into_string().unwrap();

    assert_eq!(
        expanded,
        "{path=a/folder/file.txt \
        basename=file.txt \
        parent=a/folder \
        noExt=a/folder/file \
        basenameNoExt=file }"
    );
}
}
