    let mut searcher = self.builder.build();
    let result = searcher.search_reader(
        &self.matcher,
        haystack.as_bytes(),
        &mut sink,
    );
    if let Err(err) = result {
        let label = format!("reader-{}", self.label);
        panic!("error running '{}': {}", label, err);
    }
