fn and_ngrams(&mut self, size: usize, set: &LiteralSet) {
    if set.min_len() < size {
        return;
    }
    let mut qor = GramQuery::nothing();
    for lit in &set.lits {
        if lit.len() < size {
            continue;
        }

        let mut set = LiteralSet::new();
        set.extend(ngrams(size, lit).map(BString::from));
        qor.union(GramQuery::from_set_and(set));
    }
    self.intersect(qor);
}
