pub(crate) fn find(
    &mut self,
    slice: &[u8],
) -> Result<Option<Range>, S::Error> {
    if self.has_exceeded_match_limit() {
        return Ok(None);
    }
    match self.matcher().find(slice) {
        Err(err) => Err(S::Error::error_message(err)),
        Ok(None) => Ok(None),
        Ok(Some(m)) => {
            self.increment_count();
            Ok(Some(m))
        }
    }
}
