fn try_find_iter<F, E>(
    &self,
    haystack: &[u8],
    mut matched: F,
) -> Result<Result<(), E>, NoError>
where
    F: FnMut(Match) -> Result<bool, E>,
{
    for m in self.regex.find_iter(haystack) {
        match matched(Match::new(m.start(), m.end())) {
            Ok(true) => continue,
            Ok(false) => return Ok(Ok(())),
            Err(err) => return Ok(Err(err)),
        }
    }
    Ok(Ok(()))
}
