fn from_str(s: &str) -> Result<HyperlinkFormat, HyperlinkFormatError> {
    use self::HyperlinkFormatErrorKind::*;

    #[derive(Debug)]
    enum State {
        Verbatim,
        VerbatimCloseVariable,
        OpenVariable,
        InVariable,
    }

    let mut builder = FormatBuilder::new();
    let input = match HyperlinkAlias::find(s) {
        Some(alias) => alias.format(),
        None => s,
    };
    let mut name = String::new();
    let mut state = State::Verbatim;
    let err = |kind| HyperlinkFormatError { kind };
    for ch in input.chars() {
        state = match state {
            State::Verbatim => {
                if ch == '{' {
                    State::OpenVariable
                } else if ch == '}' {
                    State::VerbatimCloseVariable
                } else {
                    builder.append_char(ch);
                    State::Verbatim
                }
            }
            State::VerbatimCloseVariable => {
                if ch == '}' {
                    builder.append_char('}');
                    State::Verbatim
                } else {
                    return Err(err(InvalidCloseVariable));
                }
            }
            State::OpenVariable => {
                if ch == '{' {
                    builder.append_char('{');
                    State::Verbatim
                } else {
                    name.clear();
                    if ch == '}' {
                        builder.append_var(&name)?;
                        State::Verbatim
                    } else {
                        name.push(ch);
                        State::InVariable
                    }
                }
            }
            State::InVariable => {
                if ch == '}' {
                    builder.append_var(&name)?;
                    State::Verbatim
                } else {
                    name.push(ch);
                    State::InVariable
                }
            }
        };
