fn matches_all(&self, candidate: &Candidate<'_>) -> bool {
    if candidate.ext.is_empty() {
        return false;
    }
    if let Some(regexes) = self.0.get(candidate.ext.as_bytes()) {
        for &(_, ref re) in regexes {
            if !re.is_match(candidate.path.as_bytes()) {
                return false;
            }
        }
