pub(crate) fn from_path(
    depth: usize,
    pb: PathBuf,
    follow: bool,
) -> Result<DirEntry> {
    let md = if follow {
        fs::metadata(&pb)
            .map_err(|err| Error::from_path(depth, pb.clone(), err))?
    } else {
        fs::symlink_metadata(&pb)
            .map_err(|err| Error::from_path(depth, pb.clone(), err))?
    };
    Ok(DirEntry {
        path: pb,
        ty: md.file_type(),
        follow_link: follow,
        depth,
        metadata: md,
    })
}
