fn print_count<W1, W2>(
    args: &Args,
    mut stdout: W1,
    mut stderr: W2,
) -> Result<()>
where
    W1: io::Write,
    W2: io::Write,
{
    let mut count: u64 = 0;
    for dir in &args.dirs {
        for result in args.walkdir(dir) {
            match result {
                Ok(_) => count += 1,
                Err(err) => {
                    if !args.ignore_errors {
                        writeln!(stderr, "ERROR: {}", err)?;
                    }
                }
            }
        }
    }
    writeln!(stdout, "{}", count)?;
    Ok(())
}
