fn parse(&mut self) -> Result<(), Error> {
    while let Some(c) = self.bump() {
        match c {
            '?' => self.push_token(Token::Any)?,
            '*' => self.parse_star()?,
            '[' if !self.found_unclosed_class => self.parse_class()?,
            '{' => self.push_alternate()?,
            '}' => self.pop_alternate()?,
            ',' => self.parse_comma()?,
            '\\' => self.parse_backslash()?,
            c => self.push_token(Token::Literal(c))?,
        }
    }
    Ok(())
}
