fn stops_at_git_dir() {
    // This tests that .gitignore files beyond a .git barrier aren't
    // matched, but .ignore files are.
    let td = tmpdir();
    mkdirp(td.path().join(".git"));
    mkdirp(td.path().join("foo/.git"));
    wfile(td.path().join(".gitignore"), "foo");
    wfile(td.path().join(".ignore"), "bar");

