fn from_entry_os(
    depth: usize,
    ent: &fs::DirEntry,
    ty: fs::FileType,
) -> Result<DirEntryRaw, Error> {
    let md = ent.metadata().map_err(|err| {
        let err = Error::Io(err).with_depth(depth).with_path(ent.path());
        Error::WithDepth { depth, err: Box::new(err) }
    })?;
    Ok(DirEntryRaw {
        path: ent.path(),
        ty,
        follow_link: false,
        depth,
        metadata: md,
    })
}
