fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
    let stdout = match self.child.stdout {
        None => return Ok(0),
        Some(ref mut stdout) => stdout,
    };
    let nread = stdout.read(buf)?;
    if nread == 0 {
        self.eof = true;
        self.close().map(|_| 0)
    } else {
        Ok(nread)
    }
}
