fn replace<F>(
    &self,
    haystack: &[u8],
    dst: &mut Vec<u8>,
    mut append: F,
) -> Result<(), Self::Error>
where
    F: FnMut(Match, &mut Vec<u8>) -> bool,
{
    let mut last_match = 0;
    self.find_iter(haystack, |m| {
        dst.extend(&haystack[last_match..m.start]);
        last_match = m.end;
        append(m, dst)
    })?;
    dst.extend(&haystack[last_match..]);
    Ok(())
}
