fn update(&self, v: FlagValue, args: &mut LowArgs) -> anyhow::Result<()> {
    let kind = match convert::str(&v.unwrap_value())? {
        "none" => {
            args.sort = None;
            return Ok(());
        }
        "path" => SortModeKind::Path,
        "modified" => SortModeKind::LastModified,
        "accessed" => SortModeKind::LastAccessed,
