fn from_set_and(mut set: LiteralSet) -> GramQuery {
    if set.is_empty() {
        GramQuery::anything()
    } else if set.len() == 1 {
        GramQuery::Literal(set.lits.pop().unwrap())
    } else {
        let lits: Vec<_> =
            set.lits.into_iter().map(GramQuery::Literal).collect();
        GramQuery::And(lits)
    }
