        anyhow::bail!(
            "A path separator must be exactly one byte, but \
             the given separator is {len} bytes: {sep}\n\
             In some shells on Windows '/' is automatically \
             expanded. Use '//' instead.",
            len = raw.len(),
            sep = s,
        )
    };
    Ok(())
}
