pub fn exit(self) -> ! {
    #[cfg(unix)]
    if self == ExitCode::KilledBySigint {
        // Get rid of the SIGINT handler, if present, and raise SIGINT
        unsafe {
            if signal(Signal::SIGINT, SigHandler::SigDfl).is_ok() {
                let _ = raise(Signal::SIGINT);
            }
        }
    }

    process::exit(self.into())
}
