fn from_ast_class_set(&mut self, ast: &ast::ClassSet) {
    if self.done() {
        return;
    }
    match *ast {
        ast::ClassSet::Item(ref item) => {
            self.from_ast_class_set_item(item);
        }
        ast::ClassSet::BinaryOp(ref x) => {
            self.from_ast_class_set(&x.lhs);
            self.from_ast_class_set(&x.rhs);
        }
    }
}
