fn interpolate<F>(
    &self,
    name_to_index: F,
    haystack: &[u8],
    replacement: &[u8],
    dst: &mut Vec<u8>,
) where
    F: FnMut(&str) -> Option<usize>,
{
    interpolate(
        replacement,
        |i, dst| {
            if let Some(range) = self.get(i) {
                dst.extend(&haystack[range]);
            }
        },
        name_to_index,
        dst,
    )
}
```

