    let mut m = one_matcher(&builder(td.path()));
    assert!(matchedf(&mut m, ".hidden-file").is_whitelist());
    let dir = matchedd(&mut m, ".hidden-dir");
    assert!(dir.is_whitelist());
    assert!(dir.should_descend());
}
