fn is_match(&self, candidate: &Candidate<'_>) -> bool {
    if candidate.ext.is_empty() {
        return false;
    }
    match self.0.get(candidate.ext.as_bytes()) {
        None => false,
        Some(regexes) => {
            for &(_, ref re) in regexes {
                if re.is_match(candidate.path.as_bytes()) {
                    return true;
                }
            }
            false
        }
    }
}
