pub fn add(&mut self, name: &str, glob: &str) -> Result<(), Error> {
    if name == "all" || !name.chars().all(|c| c.is_alphanumeric()) {
        return Err(Error::InvalidDefinition);
    }
    let (key, glob) = (name.to_string(), glob.to_string());
    self.types
        .entry(key)
        .or_insert_with(|| FileTypeDef {
            name: name.to_string(),
            globs: vec![],
        })
        .globs
        .push(glob);
    Ok(())
}
