fn from_path(
    depth: usize,
    pb: PathBuf,
    link: bool,
) -> Result<DirEntryRaw, Error> {
    use std::os::unix::fs::MetadataExt;

    let md = fs::metadata(&pb)
        .map_err(|err| Error::Io(err).with_depth(depth).with_path(&pb))?;
    Ok(DirEntryRaw {
        path: pb,
        ty: md.file_type(),
        follow_link: link,
        depth,
        ino: md.ino(),
    })
}
