        self.search_reader(path, &mut io::stdin().lock())
    } else if self.should_preprocess(path) {
        self.search_preprocessor(path)
    } else if self.should_decompress(path) {
        self.search_decompress(path)
    } else {
        self.search_path(path)
    }
}
