fn next(&mut self) -> Option<Result<DirEntry>> {
    loop {
        let dent = match self.it.next() {
            None => return None,
            Some(result) => itry!(result),
        };
        if !(self.predicate)(&dent) {
            if dent.is_dir() {
                self.it.skip_current_dir();
            }
            continue;
        }
        return Some(Ok(dent));
    }
}
