        td.path().join("a/b/c"),
    ]));
    assert!(matchedf(&mut mats[0], "first.tmp").is_ignore());
    assert!(matchedf(&mut mats[0], "c/first.tmp").is_ignore());

    // Even though we haven't used the second matcher, it should still
