pub(crate) fn new(mut n: u64) -> DecimalFormatter {
    let mut buf = [0; Self::MAX_U64_LEN];
    let mut i = buf.len();
    loop {
        i -= 1;

        let digit = u8::try_from(n % 10).unwrap();
        n /= 10;
        buf[i] = b'0' + digit;
        if n == 0 {
            break;
        }
    }
    DecimalFormatter { buf, start: i }
}
