function locEnd(node) {
  const { type } = node;

  // Effected by children
  if (type === "IfStatement") {
    return locEnd(node.alternate ?? node.consequent);
  }

  if (
    type === "ForInStatement" ||
    type === "ForOfStatement" ||
    type === "ForStatement" ||
    type === "LabeledStatement" ||
    type === "WithStatement" ||
    type === "WhileStatement"
  ) {
    return locEnd(node.body);
  }

  return (
    overrides.get(type)?.(
      // @ts-expect-error -- Comment types
      node,
    ) ?? locEndWithFullText(node)
  );
}
```

