function printChildren(path, options, print, events = {}) {
  const { processor = print } = events;

  const parts = [];

  path.each(() => {
    const result = processor(path);
    if (result !== false) {
      if (parts.length > 0 && shouldPrePrintHardline(path)) {
        parts.push(hardline);

        if (shouldPrePrintDoubleHardline(path, options)) {
          parts.push(hardline);
        }
      }

      parts.push(result);
    }
  }, "children");

  return parts;
}
