  /* c8 ignore next 3 */
  if (!node.selector) {
    return false;
  }

  return node.selector
    .replace(/\/\*.*?\*\//, "")
    .replace(/\/\/.*\n/, "")
    .trimEnd()
    .endsWith(":");
}
