	return (
		code

			// Code blocks always contain an extra line break at the end, so remove it.
			.replace(/\n$/u, "")

			// Replace LF line breaks with CRLF after `\r\n` sequences.
			.replace(/(?<=\\r\\n)\n/gu, "\r\n")

			// Remove presentational `⏎` characters at the end of lines.
			.replace(/⏎(?=\n)/gu, "")
	);
}
```

