	// Undefined globals.
	for (const reference of scope.through) {
		const id = reference.identifier;

		if (
			isGoodName(id.name) ||
			astUtils.isImportAttributeKey(id)
		) {
			continue;
		}

		/*
		 * For backward compatibility, this rule reports read-only
		 * references as well.
		 */
		reportReferenceId(id);
	}
}
