function equal(a, b) {
	if (a.type !== b.type) {
		return false;
	}

	if (
		a.type === "LogicalExpression" &&
		(a.operator === "||" || a.operator === "&&") &&
		a.operator === b.operator
	) {
		return (
			(equal(a.left, b.left) && equal(a.right, b.right)) ||
			(equal(a.left, b.right) && equal(a.right, b.left))
		);
	}

	return astUtils.equalTokens(a, b, sourceCode);
}
