function liquidFromMarkdown() {
  return {
    canContainEols: [nodeType],
    enter: { [nodeType]: enter },
    exit: { [nodeType]: exit },
  };

  /** @type {Handle} */
  function enter(token) {
    this.enter(
      // @ts-expect-error
      { type: nodeType },
      token,
    );
    this.buffer();
  }

  /** @type {Handle} */
  function exit(token) {
    this.resume();
    /** @type {any} */
    const node = this.stack.at(-1);
    node.value = this.sliceSerialize(token);
    this.exit(token);
  }
}
