getTrailingWhitespaceCount(text) {
  const whitespaceCharacters = this.#whitespaceCharacters;
  let count = 0;

  for (
    let index = text.length - 1;
    index >= 0 && whitespaceCharacters.has(text.charAt(index));
    index--
  ) {
    count++;
  }

  return count;
}
