        if (node.type === "code" && node.isIndented) {
          return print();
        }

        const alignment = " ".repeat(
          clamp(options.tabWidth - listPrefix.length, 0, 3), // 4+ will cause indented code block
        );
        return [alignment, align(alignment, print())];
      },
    }),
  ];
}
