function tagOpenAttributeValueUnquoted(code) {
  if (
    code === codes.eof ||
    code === codes.quotationMark ||
    code === codes.apostrophe ||
    code === codes.lessThan ||
    code === codes.equalsTo ||
    code === codes.graveAccent
  ) {
    return nok(code);
