```javascript
function iterateBidiSections(order, from, to, f) {
    if (!order) {
        return f(from, to, "ltr", 0)
    }
    var found = false
    for (var i = 0; i < order.length; ++i) {
        var part = order[i]
        if ((part.from < to && part.to > from) || (from == to && part.to == from)) {
            f(
                Math.max(part.from, from),
                Math.min(part.to, to),
                part.level == 1 ? "rtl" : "ltr",
                i
            )
            found = true
        }
    }
    if (!found) {
        f(from, to, "ltr")
    }
}
