function visualLineEndNo(doc, lineN) {
    if (lineN > doc.lastLine()) {
        return lineN
    }
    var line = getLine(doc, lineN),
        merged
    if (!lineIsHidden(doc, line)) {
        return lineN
    }
    while ((merged = collapsedSpanAtEnd(line))) {
