function findSourcemaps(dir) {
  if (!existsSync(dir)) return []
  /** @type {string[]} */
  const found = []
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry)
    if (statSync(full).isDirectory()) {
      found.push(...findSourcemaps(full))
    } else if (entry.endsWith('.map')) {
      found.push(full)
    }
  }
  return found
}
