function handleArrowExpressionComments({
  comment,
  enclosingNode,
  followingNode,
  precedingNode,
  options,
}) {
  if (
    enclosingNode?.type !== "ArrowFunctionExpression" ||
    !followingNode ||
    !precedingNode
  ) {
    return false;
  }

  const isBeforeArrow = isCommentBeforeArrowFunctionExpressionArrow(
    comment,
    enclosingNode,
    options,
  );

  if (!isBeforeArrow) {
    addBlockOrNotComment(followingNode, comment);
    return true;
  }

  return false;
}
