__iterator(type, reverse) {
  const cache = this._cache;
  if (cache) {
    const size = cache.length;
    let i = 0;
    return new Iterator(() => {
      if (i === size) {
        return iteratorDone();
      }
      const entry = cache[reverse ? size - ++i : i++];
      return iteratorValue(type, entry[0], entry[1]);
    });
  }
  return this.__iteratorUncached(type, reverse);
}
