    return error;
  }

  const { line, column } = loc;
  let [message] = error.message.split("\n", 1);

  const suffix = ` (${line}:${column})`;
  if (message.endsWith(suffix)) {
    message = message.slice(0, -suffix.length);
  }

  return createError(message, {
    loc: {
      start: { line, column: column + 1 },
    },
    cause: error,
  });
}
