function expandHeadingPseudoClassSelector(selector) {
  if (selector === ":heading") {
    return ["h1", "h2", "h3", "h4", "h5", "h6"];
  }

  const match = selector.match(/^:heading\((?<levels>\d+(?:,\s*\d+)*)\)$/);
  if (!match) {
    return;
  }

  return match.groups.levels.split(",").map((level) => `h${level.trim()}`);
}
