      leftNode.type === "ObjectPattern" &&
      leftNode.properties.length > 2 &&
      leftNode.properties.some(
        (property) =>
          isObjectProperty(property) &&
          (!property.shorthand || property.value?.type === "AssignmentPattern"),
      )
    );
  }
  return false;
}
