__iterator(type, reverse) {
  const size = this.size;
  const step = this._step;
  let value = reverse ? this._start + (size - 1) * step : this._start;
  let i = 0;
  return new Iterator(() => {
    if (i === size) {
      return iteratorDone();
    }
    const v = value;
    value += reverse ? -step : step;
    return iteratorValue(type, reverse ? size - ++i : i++, v);
  });
}
