```javascript
function countColumn(string, end, tabSize, startIndex, startValue) {
    if (end == null) {
        end = string.search(/[^\s\u00a0]/)
        if (end == -1) {
            end = string.length
        }
    }
    for (var i = startIndex || 0, n = startValue || 0; ; ) {
        var nextTab = string.indexOf("\t", i)
        if (nextTab < 0 || nextTab >= end) {
            return n + (end - i)
        }
        n += nextTab - i
        n += tabSize - (n % tabSize)
        i = nextTab + 1
    }
}
```

