__iterate(fn, reverse) {
  if (reverse) {
    return new ArraySeq(this.toArray()).__iterate(
      (v, k) => fn(v, k, this),
      reverse
    );
  }
  let iterations = 0;
  let node = this._head;
  while (node) {
    if (fn(node.value, iterations++, this) === false) {
      break;
    }
    node = node.next;
