function checkBinaryExpression(node) {
	if (
		/^(?:[<>]|[!=]=)=?$/u.test(node.operator) &&
		(isNaNIdentifier(node.left, sourceCode) ||
			isNaNIdentifier(node.right, sourceCode))
	) {
		const suggestedFixes = [];
		const NaNNode = isNaNIdentifier(node.left, sourceCode)
			? node.left
			: node.right;

		const isSequenceExpression =
			NaNNode.type === "SequenceExpression";
		const isSuggestable =
			fixableOperators.has(node.operator) &&
			!isSequenceExpression;
		const isCastable = castableOperators.has(node.operator);

		if (isSuggestable) {
			suggestedFixes.push({
				messageId: "replaceWithIsNaN",
				fix: getBinaryExpressionFixer(
					node,
					value => `Number.isNaN(${value})`,
				),
			});

			if (isCastable) {
				suggestedFixes.push({
					messageId: "replaceWithCastingAndIsNaN",
					fix: getBinaryExpressionFixer(
						node,
						value => `Number.isNaN(Number(${value}))`,
					),
				});
			}
		}

		context.report({
			node,
			messageId: "comparisonWithNaN",
			suggest: suggestedFixes,
		});
	}
}
