function readPortFromEnv(name, fallback) {
  const rawValue = process.env[name]
  if (!rawValue) {
    return fallback
  }

  const parsed = Number.parseInt(rawValue, 10)
  const valid = Number.isInteger(parsed) && parsed >= 1 && parsed <= 65535

