  if (node.type === "ImportExpression") {
    return `import${node.phase ? `.${node.phase}` : ""}`;
  }

  if (node.type === "TSImportType") {
    return "import";
  }

  if (node.type === "TSExternalModuleReference") {
    return "require";
  }

  return [
