    return {};
  }

  const dir = path.dirname(file);

  return {
    [selector](node) {
      const { value } = node;

      if (
        !value.startsWith(".") ||
        !value.endsWith("/document/public.js") ||
        path.join(dir, value) !== docIndexFile
      ) {
        return;
      }

      context.report({
        node,
        messageId,
        data: {
          type: node.parent.type.slice(0, 6).toLowerCase(),
        },
        fix: fix(node, context),
      });
