function printTypeParameter(path, options, print) {
  const { node } = path;

  /**
   * @type {Doc[]}
   */
  const parts = [node.const ? "const " : ""];

  const name = node.type === "TSTypeParameter" ? print("name") : node.name;

  if (node.variance) {
    parts.push(print("variance"));
  }

  if (node.in) {
    parts.push("in ");
  }

  if (node.out) {
