function findInsertionTokenAfterParens(firstToken, lastToken) {
	const lastIndex = lastToken.range[1];
	let token = firstToken;
	let nextToken = sourceCode.getTokenAfter(token);

	while (
		nextToken.range[1] <= lastIndex &&
