		codeBlockToken.info === "ts" || codeBlockToken.info === "tsx";

	prismESLintHook.addContentMustBeMarked(
		codeBlockToken.content,
		isTypeScriptCode
			? { ...languageOptions, parser: typescriptESLintParser }
			: languageOptions,
	);

	const isRuleRemoved = !Object.hasOwn(env.rules_meta, env.title);

	const tsLanguageOptions = {
		languageOptions: {
			...languageOptions,
			parser: "@typescript-eslint/parser",
			parserOptions: {
				ecmaFeatures: {
					jsx: true,
				},
			},
		},
	};

	const languageOptionsForPlayground = languageOptions
		? { languageOptions }
		: void 0;

	if (isRuleRemoved) {
		return `<div class="${type}">`;
	}

	// See https://github.com/eslint/eslint.org/blob/29e1d8a000592245e4a30c1996e794643e9b263a/src/playground/App.js#L91-L105
	const state = encodeToBase64(
		JSON.stringify({
			options: isTypeScriptCode
				? tsLanguageOptions
				: languageOptionsForPlayground,
			text: code,
		}),
	);
	const prefix =
		process.env.CONTEXT && process.env.CONTEXT !== "deploy-preview"
			? ""
			: "https://eslint.org";

