export function debounceByArgs(func, waitFor) {
  const timeouts = {};

  return (...args) => {
    const argsKey = JSON.stringify(args);
    const later = () => {
      delete timeouts[argsKey];
      func(...args);
    };
    clearTimeout(timeouts[argsKey]);
    timeouts[argsKey] = setTimeout(later, waitFor);
  };
}
