  memcpy(&once, &child_once, sizeof(child_once));

  /* reset epoll list */
  while (!uv__queue_empty(&global_epoll_queue)) {
    uv__os390_epoll* lst;
    q = uv__queue_head(&global_epoll_queue);
    uv__queue_remove(q);
    lst = uv__queue_data(q, uv__os390_epoll, member);
    uv__free(lst->items);
    lst->items = NULL;
    lst->size = 0;
