static void uv__windows10_version1709_init(void) {
  OSVERSIONINFOW os_info;

  if (!pRtlGetVersion)
    return;

  os_info.dwOSVersionInfoSize = sizeof(os_info);
  os_info.szCSDVersion[0] = L'\0';

  if (pRtlGetVersion(&os_info) != STATUS_SUCCESS)
