  uv_mutex_lock(&global_epoll_lock);
  uv__queue_foreach(q, &global_epoll_queue) {
    uv__os390_epoll* lst;

    lst = uv__queue_data(q, uv__os390_epoll, member);
    if (fd < lst->size && lst->items != NULL && lst->items[fd].fd != -1)
