			if !disablePathNormalizing && !isSingleSegment(ph.value) {
				return "", fmt.Errorf("%w: %q", ErrPathParamInPath, ph.name)
			}
			buf = utils.AppendPathEscape(buf, ph.value)
		}
		last = ph.end
		i = ph.end - 1
	}

	if buf == nil {
		return uri, nil
	}

	return string(append(buf, uri[last:]...)), nil
}
