		return append(dst, '[', ']')
	}
	dst = append(dst, '[')
	dst = e.AppendString(dst, ips[0].String())
	if len(ips) > 1 {
		for _, ip := range ips[1:] {
			dst = e.AppendString(append(dst, ','), ip.String())
		}
	}
	dst = append(dst, ']')
	return dst
}
