func (a *Array) Errs(errs []error) *Array {
	for _, err := range errs {
		switch m := ErrorMarshalFunc(err).(type) {
		case nil:
			a = a.Interface(nil)
		case LogObjectMarshaler:
			a = a.Object(m)
		case error:
			if !isNilValue(m) {
				a = a.Str(m.Error())
			}
		case string:
			a = a.Str(m)
		default:
			a = a.Interface(m)
		}
	}
	return a
}
