func sanitizeJSONPCallback(cb string) string {
	i := 0
	for ; i < len(cb); i++ {
		if !isJSONPCallbackByte(cb[i]) {
			break
		}
	}

	if i != len(cb) {
		out := make([]byte, i, len(cb))
		copy(out, cb[:i])
		for ; i < len(cb); i++ {
			if isJSONPCallbackByte(cb[i]) {
				out = append(out, cb[i])
			}
		}
		cb = utils.UnsafeString(out)
	}

	if !isJSONPMemberExpression(cb) {
		return ""
	}
	return cb
}
