func isValidToken68(token string) bool {
	if token == "" || token[0] == '=' {
		return false // Empty, or starting with padding
	}
	i := 0
	for i < len(token) && token68Chars[token[i]] {
		i++
	}
	// Whatever stopped the scan must be padding, and so must the rest.
	for ; i < len(token); i++ {
		if token[i] != '=' {
			return false
		}
	}
	return true
}
