func (e Encoder) AppendIPPrefixes(dst []byte, pfxs []net.IPNet) []byte {
	if len(pfxs) == 0 {
		return append(dst, '[', ']')
	}
	dst = append(dst, '[')
	dst = e.AppendString(dst, pfxs[0].String())
	if len(pfxs) > 1 {
		for _, pfx := range pfxs[1:] {
			dst = e.AppendString(append(dst, ','), pfx.String())
		}
	}
	dst = append(dst, ']')
	return dst
}
