func (c *core) timeout() context.CancelFunc {
	var cancel context.CancelFunc

	if c.req.timeout > 0 {
		c.ctx, cancel = context.WithTimeout(c.ctx, c.req.timeout)
	} else {
		c.client.mu.RLock()
		timeout := c.client.timeout
		c.client.mu.RUnlock()
		if timeout > 0 {
			c.ctx, cancel = context.WithTimeout(c.ctx, timeout)
		}
	}

	return cancel
}
