func encodeQueryValues(q url.Values) string {
	if len(q) == 0 {
		return ""
	}
	keys := make([]string, 0, len(q))
	for k := range q {
		keys = append(keys, k)
	}
	slices.Sort(keys)
	var buf []byte
	for _, k := range keys {
		for _, v := range q[k] {
			if len(buf) > 0 {
				buf = append(buf, '&')
			}
			buf = utils.AppendQueryEscape(buf, k)
			buf = append(buf, '=')
			buf = utils.AppendQueryEscape(buf, v)
		}
	}
	return utils.UnsafeString(buf)
}
