func wordAt(s string, i int) uint64 {
	rest := len(s) - i
	if rest >= swar.WordLen {
		return swar.Load8(s, i)
	}
	if len(s) >= swar.WordLen {
		return swar.Load8(s, len(s)-swar.WordLen) >> (8 * (swar.WordLen - rest))
	}
	return pathHeadWord(s[i:])
