func (l *MemoryLock) Lock(key string) error {
	l.mu.Lock()
	if l.keys == nil {
		l.keys = make(map[string]*countedLock)
	}
	lock, ok := l.keys[key]
	if !ok {
		lock = new(countedLock)
		l.keys[key] = lock
	}
	lock.locked++
	l.mu.Unlock()

	lock.mu.Lock()

	return nil
}
