func All(list string) iter.Seq[string] {
	return func(yield func(string) bool) {
		start := 0
		for i := range len(list) {
			if list[i] != ',' {
				continue
			}
			if element := utils.TrimSpace(list[start:i]); element != "" {
				if !yield(element) {
					return
				}
			}
			start = i + 1
		}
		if element := utils.TrimSpace(list[start:]); element != "" {
			yield(element)
		}
	}
}
