func isCanonicalName(name []byte) bool {
	upper := true
	for _, c := range name {
		if upper {
			if c >= 'a' && c <= 'z' {
				return false
			}
		} else if c >= 'A' && c <= 'Z' {
			return false
		}
		upper = c == '-'
	}
	return true
}
