func (app *App) startGracefulShutdown(cfg *ListenConfig) func() {
	if cfg.GracefulContext == nil {
		return func() {}
	}

	done := make(chan struct{})
	stop := context.AfterFunc(cfg.GracefulContext, func() {
		defer close(done)
		app.gracefulShutdown(cfg)
	})

	return func() {
		if !stop() {
			<-done
		}
	}
}
