func cleanPathSegments(b []byte) []byte {
	if !hasDotSegment(b) {
		return b
	}
	n := len(b)
	rooted := b[0] == '/'
	i := 0
	if rooted {
		i = 1
	}
	w := 0
	trailingSlash := false
	for i <= n {
		j := i
		for j < n && b[j] != '/' {
			j++
		}
		seg := b[i:j]
		last := j == n
		switch {
		case len(seg) == 1 && seg[0] == '.':
			trailingSlash = last
		case len(seg) == 2 && seg[0] == '.' && seg[1] == '.':
			if k := bytes.LastIndexByte(b[:w], '/'); k >= 0 {
				w = k
			} else {
				w = 0
			}
			trailingSlash = last
		default:
			if rooted || w > 0 {
				b[w] = '/'
				w++
			}
			w += copy(b[w:], seg)
			trailingSlash = false
		}
		i = j + 1
	}
	if trailingSlash && (w == 0 || b[w-1] != '/') {
		b[w] = '/'
		w++
	}
	return b[:w]
}
