func knownPrefix(r *Route) string {
	if r.star {
		return ""
	}

	prefix := r.path
	if len(r.Params) > 0 {
		segs := r.routeParser.segs
		if len(segs) == 0 || segs[0].IsParam {
			return ""
		}
		prefix = segs[0].Const
		if segs[0].HasOptionalSlash {
			prefix = prefix[:len(prefix)-1]
		}
	}
	return prefix
}
