func processInput(reader io.Reader, writer io.Writer) error {
	scanner := bufio.NewScanner(reader)
	for scanner.Scan() {
		bytesToWrite := scanner.Bytes()
		_, err := writer.Write(bytesToWrite)
		if err != nil {
			if errors.Is(err, io.EOF) {
				break
			}

			fmt.Printf("%s\n", bytesToWrite)
		}
	}

	return scanner.Err()
}
