	for ; i+swar.WordLen <= n; i += swar.WordLen {
		if visibleASCIIMask(swar.Load8(rid, i)) != swar.HighBits {
			return false
		}
	}
	if i == n {
		return true
	}
	if n >= swar.WordLen {
		return visibleASCIIMask(swar.Load8(rid, n-swar.WordLen)) == swar.HighBits
	}
	for ; i < n; i++ {
		if c := rid[i]; c < 0x20 || c > 0x7e {
			return false
		}
	}

	return true
}
