func appendIfAbsent(list string, values []string, present func(list, value string) bool) string {
	original := list
	for _, value := range values {
		if value == "" {
			continue
		}
		switch {
		case list == "":
			list = value
		case !present(list, value):
			list += ", " + value
		}
	}

	if list == original {
		return ""
	}
	return list
}
