func (r *DefaultRouter) Add(route Route) (RouteInfo, error) {
	allowOverwritingRoute := r.allowOverwritingRoute || route.allowOverwrite

	if route.Handler == nil {
		switch route.Method {
		case RouteNotFound:
			route.Handler = r.notFoundHandler
		case http.MethodOptions:
			route.Handler = r.optionsMethodHandler
		default:
			return RouteInfo{}, newAddRouteError(route, errors.New("adding route without handler function"))
		}
	}

	method := route.Method
	path := normalizePathSlash(route.Path)

	h := applyMiddleware(route.Handler, route.Middlewares...)
	if !allowOverwritingRoute {
		for _, rr := range r.routes {
			if route.Method == rr.Method && route.Path == rr.Path {
				return RouteInfo{}, newAddRouteError(route, errors.New("adding duplicate route (same method+path) is not allowed"))
			}
		}
	}
	var headH HandlerFunc
	if r.autoHandleHEAD && method == http.MethodGet {
		headH = wrapHeadHandler(h)
	}

	parts := parseRoutePath(path)
	var paramNames []string
	for _, part := range parts {
		if part.kind == paramKind {
			paramNames = append(paramNames, part.value)
		} else if part.kind == anyKind {
			paramNames = append(paramNames, "*")
			break
		}
	}
	ri := route.ToRouteInfo(paramNames)
	rm := routeMethod{
		RouteInfo:          &RouteInfo{Method: method, Path: path, Parameters: paramNames, Name: route.Name},
		handler:            h,
		orgRouteInfo:       ri,
		wrappedHeadHandler: headH,
	}
	partial := routeMethod{RouteInfo: &RouteInfo{Method: method}}
	treePath, paramMarkers := routeTreePath(parts)
	pathEnd := 0
addParts:
	for i, part := range parts {
		switch part.kind {
		case staticKind:
			pathEnd += len(part.value)
			if i == len(parts)-1 {
				r.insert(staticKind, treePath[:pathEnd], method, rm, paramMarkers)
			}
		case paramKind:
			r.insert(staticKind, treePath[:pathEnd], method, partial, paramMarkers)
			pathEnd++
			if i == len(parts)-1 {
				r.insert(paramKind, treePath[:pathEnd], method, rm, paramMarkers)
			} else {
				r.insert(paramKind, treePath[:pathEnd], method, partial, paramMarkers)
			}
		case anyKind:
			r.insert(staticKind, treePath[:pathEnd], method, partial, paramMarkers)
			pathEnd++
			r.insert(anyKind, treePath[:pathEnd], method, rm, paramMarkers)
			break addParts
		}
	}

	r.storeRouteInfo(ri)

	return ri, nil
}
```

