func isValidJSONPCallback(callback string) bool {
	if callback == "" {
		return true
	}
	atStart := true // at the start of an identifier
	for i := 0; i < len(callback); i++ {
		ch := callback[i]
		switch {
		case ch == '.':
			if atStart {
				return false
			}
			atStart = true
		case ch == '_' || ch == '$' || ('a' <= ch && ch <= 'z') || ('A' <= ch && ch <= 'Z'):
			atStart = false
		case '0' <= ch && ch <= '9':
			if atStart {
				return false
			}
		default:
			return false
		}
	}
	return !atStart
}
```

