			atStart = true
		case ch == '_' || ch == '$' || ('a' <= ch && ch <= 'z') || ('A' <= ch && ch <= 'Z'):
			atStart = false
		case '0' <= ch && ch <= '9':
			if atStart {
				return false
			}
		default:
			return false
		}
	}
	return !atStart
}
