func pathFingerprint[S ~string | ~[]byte](s S) uint64 {
	h := fingerprintBasis ^ uint64(len(s))
	i := 0
	for ; i+swar.WordLen <= len(s); i += swar.WordLen {
		h = (h ^ swar.Load8(s, i)) * fingerprintPrime
		h ^= h >> 31
	}
	var tail uint64
	for ; i < len(s); i++ {
		tail = tail<<8 | uint64(s[i])
	}
	h = (h ^ tail) * fingerprintPrime
	h ^= h >> 31
	return h | 1
}
```

