func IsCanonical(name string) bool {
	n := len(name)
	if n == 0 {
		return false
	}
	// Names such as X-Request-ID fail only at their last byte, so the tail is
	// checked first: an upper-case letter not following a '-' cannot end a
	// canonical name.
	if n > 1 && name[n-1] >= 'A' && name[n-1] <= 'Z' && name[n-2] != '-' {
		return false
	}
	upper := true
	for i := range n {
		c := name[i]
		switch keyClass[c] {
		case keyInvalid:
			return false
		case keyLower:
			if upper {
				return false
			}
		case keyUpper:
			if !upper {
				return false
			}
		}
		upper = c == '-'
	}
	return true
}
```

