	case *map[string]string:
		if m != nil {
			if *m == nil {
				*m = make(map[string]string, len(last))
			}
			maps.Copy(*m, last)
			return nil
		}
	case map[string]string:
		if m == nil {
			return ErrMapNilDestination
		}
		maps.Copy(m, last)
		return nil
	}
	return parse(aliasTag, out, nil)
}
