func bindModeFor(out any) bindMode {
	switch out.(type) {
	case *map[string][]string, map[string][]string:
		return bindMap
	case *map[string]string, map[string]string:
		return bindLast
	}
	t := reflect.TypeOf(out)
	if t == nil {
		return bindPairs
	}
	if t.Kind() == reflect.Pointer {
		t = t.Elem()
	}
	if t.Kind() != reflect.Map || t.Key().Kind() != reflect.String {
		return bindPairs
	}
	return bindMap
}
