export default function Films() {
  const { data, status } = useQuery({
    queryKey: ['films'],
    queryFn: () => getFilms(),
  })

  if (status === 'pending') {
    return <p>Loading...</p>
  }
  if (status === 'error') {
    return <p>Error :(</p>
  }

  return (
    <div>
      <h2 className="text-4xl">Films</h2>
      {data.results.map((film: any) => {
