        const filmId = filmUrlParts[filmUrlParts.length - 1]
        return (
          <article key={filmId}>
            <RouterLink
              className="text-blue-500 hover:underline"
              to={`/films/${filmId}`}
            >
              <h6 className="text-xl">
                {film.episode_id}. {film.title}{' '}
                <em>
                  ({new Date(Date.parse(film.release_date)).getFullYear()})
                </em>
              </h6>
            </RouterLink>
          </article>
        )
      })}
    </div>
  )
}
