      partialRoute += `"${escape(transformPatternToRoute(value, depth + 1, maxDepth, maxKeys))}"`;
    } else {
      partialRoute += transformPatternToRoute(
        value,
        depth + 1,
        maxDepth,
        maxKeys,
      );
    }

    return partialRoute;
  });

  return `{${parts.join(',')}}`;
}
