init(api, { serializeQueryArgs }, context) {
  const anyApi = api as any as Api<
    any,
    Record<string, any>,
    any,
    any,
    ReactHooksModule
  >
  const {
    buildQueryHooks,
    buildInfiniteQueryHooks,
    buildMutationHook,
    usePrefetch,
  } = buildHooks({
    api,
    moduleOptions: {
      batch,
      hooks,
      unstable__sideEffectsInRender,
      createSelector,
    },
    serializeQueryArgs,
    context,
  })
  safeAssign(anyApi, { usePrefetch })
  safeAssign(context, { batch })

  return {
    injectEndpoint(endpointName, definition) {
      if (isQueryDefinition(definition)) {
        const {
          useQuery,
          useLazyQuery,
          useLazyQuerySubscription,
          useQueryState,
          useQuerySubscription,
        } = buildQueryHooks(endpointName)
        safeAssign(anyApi.endpoints[endpointName], {
          useQuery,
          useLazyQuery,
          useLazyQuerySubscription,
          useQueryState,
          useQuerySubscription,
        })
        ;(api as any)[`use${capitalize(endpointName)}Query`] = useQuery
        ;(api as any)[`useLazy${capitalize(endpointName)}Query`] =
          useLazyQuery
      }
      if (isMutationDefinition(definition)) {
        const useMutation = buildMutationHook(endpointName)
        safeAssign(anyApi.endpoints[endpointName], {
          useMutation,
        })
        ;(api as any)[`use${capitalize(endpointName)}Mutation`] =
          useMutation
      } else if (isInfiniteQueryDefinition(definition)) {
        const {
          useInfiniteQuery,
          useInfiniteQuerySubscription,
          useInfiniteQueryState,
        } = buildInfiniteQueryHooks(endpointName)
        safeAssign(anyApi.endpoints[endpointName], {
          useInfiniteQuery,
          useInfiniteQuerySubscription,
          useInfiniteQueryState,
        })
        ;(api as any)[`use${capitalize(endpointName)}InfiniteQuery`] =
          useInfiniteQuery
      }
    },
  }
}
