  const getInputs = memo(async () => {
    const fd = await req.formData();
    return fd;
  });
  const procedure = await getProcedureAtPath(opts.router, opts.path);
  return {
    accept: null,
    calls: [
      {
        batchIndex: 0,
        path: opts.path,
        getRawInput: getInputs.read,
        result: getInputs.result,
        procedure,
      },
    ],
    isBatchCall: false,
    type: 'mutation',
    connectionParams: null,
    signal: req.signal,
    url: opts.url,
  };
}
