function getRouterErrorType(
  routerType: ts.Type,
  checker: ts.TypeChecker,
): ts.Type | null {
  const walk = (type: ts.Type, keys: string[]): ts.Type | null => {
    const [head, ...rest] = keys;
    if (!head) {
      return type;
    }
    const sym = type.getProperty(head);
    if (!sym) {
      return null;
    }
    return walk(checker.getTypeOfSymbol(sym), rest);
  };

  const errorShapeType = walk(routerType, [
    '_def',
    '_config',
    '$types',
    'errorShape',
  ]);
  if (!errorShapeType || hasFlag(errorShapeType, ts.TypeFlags.Any)) {
    return null;
  }

  return errorShapeType;
}
```

