    if (index.isFulltext && this.driver.isFullTextColumnTypeSupported()) {
        indexType += "FULLTEXT "
    }

    return new Query(
        `CREATE ${indexType}INDEX "${index.name}" ON ${this.escapePath(
            table,
        )} (${columns}) ${index.where ? "WHERE " + index.where : ""}`,
    )
}
