    !(queryThunk.rejected.match(action) && action.meta.condition)
  ) {
    pendingRequestCount = Math.max(0, pendingRequestCount - 1)
  }

  if (isThunkActionWithTags(action)) {
    invalidateTags(
      calculateProvidedByThunk(
        action,
        'invalidatesTags',
