function maxWidth(
  table:
    [string | IndentedText, ...any[]][] | Dictionary<string | IndentedText>,
  theWrap?: number | null,
  modifier?: string
) {
  let width = 0;

  // table might be of the form [leftColumn],
  // or {key: leftColumn}
  if (!Array.isArray(table)) {
    table = Object.values(table).map<[string | IndentedText]>(v => [v]);
  }

  table.forEach(v => {
    // column might be of the form "text"
    // or { text: "text", indent: 4 }
    width = Math.max(
      shim.stringWidth(
        modifier ? `${modifier} ${getText(v[0])}` : getText(v[0])
      ) + getIndentation(v[0]),
      width
    );
  });

  // if we've enabled 'wrap' we should limit
  // the max-width of the left-column.
  if (theWrap)
    width = Math.min(width, parseInt((theWrap * 0.5).toString(), 10));

  return width;
}
```

