set(key: K, value: V) {
    const hasKey = this.has_(key)
    if (hasInterceptors(this)) {
        const change = interceptChange<IMapWillChange<K, V>>(this, {
            type: hasKey ? UPDATE : ADD,
            object: this,
            newValue: value,
            name: key
        })
        if (!change) {
            return this
        }
        value = change.newValue!
    }
    if (hasKey) {
        this.updateValue_(key, value)
    } else {
        this.addValue_(key, value)
    }
    return this
}
