function removeManyMutably(keys: readonly Id[], state: R): void {
  let didMutate = false

  keys.forEach((key) => {
    if (key in state.entities) {
      delete (state.entities as Record<Id, T>)[key]
      didMutate = true
    }
  })

  if (didMutate) {
    state.ids = (state.ids as Id[]).filter((id) => id in state.entities) as
      | Id[]
      | Draft<Id[]>
  }
