        other = new Map(other)
    }
    transaction(() => {
        if (isPlainObject(other)) {
            getPlainObjectKeys(other).forEach((key: any) =>
                this.set(key as K, (other as IKeyValueMap)[key])
            )
        } else if (Array.isArray(other)) {
