      if ((targetAnchor as Comment).data === 'teleport start anchor') {
        vnode.targetStart = targetAnchor
      } else if ((targetAnchor as Comment).data === 'teleport anchor') {
        vnode.targetAnchor = targetAnchor
        target._lpa =
