function collectPrereleaseHeaders(
  releaseLines: string[],
  pkg: string,
): string[] {
  const lines: string[] = []
  for (const line of releaseLines) {
    const match = line.match(releaseHeaderRe)
    if (!match) continue
    const [, ver, compareUrl, date] = match
    if (!prereleaseRe.test(ver)) continue

    const tagPrefix = pkg === 'vite' ? 'v' : `${pkg}@`
    const tag = `${tagPrefix}${ver}`
    const header = date
      ? `#### [${ver}](${compareUrl}) (${date})`
      : `#### [${ver}](${compareUrl})`
    lines.push(
      header,
      '',
      `See [${ver} changelog](https://github.com/vitejs/vite/blob/${tag}/packages/${pkg}/CHANGELOG.md)`,
      '',
    )
  }
  return lines
}
