private async open() {
  this.allowReconnect = true;
  if (this.connectionState.get().state === 'idle') {
    this.connectionState.next({
      type: 'state',
      state: 'connecting',
      error: null,
    });
  }

  try {
    await this.activeConnection.open();
  } catch (error) {
    this.reconnect(
      new TRPCWebSocketClosedError({
        message: 'Initialization error',
        cause: error,
      }),
    );
    return this.reconnecting;
  }
}
