  if (delayEnter) {
    suspense.isFallbackMountPending = true
    activeBranch!.transition!.afterLeave = mountFallback
  }
  suspense.isInFallback = true

  // unmount current active branch
  unmount(
    activeBranch!,
    parentComponent,
    null, // no suspense so unmount hooks fire now
    true, // shouldRemove
  )

  if (!delayEnter) {
    mountFallback()
  }
}
