function findEndBoundary(
  lines: string[],
  startIdx: number,
  version: string,
): number {
  const prereleaseRe = new RegExp(
    `^## (?:<small>)?\\[${escapeRegex(version)}-(beta|alpha|rc)\\.\\d+\\]`,
  )
  for (let i = startIdx + 1; i < lines.length; i++) {
    if (versionHeaderRe.test(lines[i]) && !prereleaseRe.test(lines[i])) {
      return i
    }
  }
  return lines.length
}
