function printComplexValue(
  value: object,
  config: Config,
  depth: number,
  refs: Refs,
): string {
  if (refs.includes(value)) {
    return '[Circular]'
  }
  refs = [...refs, value]

  const hitMaxDepth = ++depth > config.maxDepth
  if (Array.isArray(value)) {
    return hitMaxDepth
      ? '[Array]'
      : `[${printListItems(value, config, depth, refs)}]`
  }
  return hitMaxDepth
    ? '[Object]'
    : `{${printObjectProperties(
        value as Record<string, unknown>,
        config,
        depth,
        refs,
      )}}`
}
```

