          while ((child = walker.nextNode())) {
            ;(child as Element).setAttribute(id, '')
          }
        }
        parent.insertBefore(n, o)
      }
    } else {
      while (o.firstChild) parent.insertBefore(o.firstChild, o)
    }
    parent.removeChild(o)
  }
}
