async function basePages(
  outputDir: string,
  from: string,
  seen: Set<string>,
): Promise<Array<string>> {
  if (seen.has(from)) {
    return []
  }
  seen.add(from)
  const page = await propertiesPage(outputDir, from)
  if (page) {
    return [page]
  }
  const code = (await readPage(outputDir, from))?.match(
    /```ts\ntype \w+(?:<[^\n=]*>)? = ([\s\S]*?);\n```/,
  )?.[1]
  return code ? basePagesOfType(outputDir, code, seen) : []
}
