```typescript
getDepth() {
  const visited = new Set<TreeNode<T>>();

  let depth = 0;
  // eslint-disable-next-line @typescript-eslint/no-this-alias
  let current: TreeNode<T> | null = this;

  while (current) {
    depth++;
    current = current.parent;

    // Stop on cycle
    if (visited.has(current!)) {
      return -1;
    }
    visited.add(current!);
  }
  return depth;
}
```

