internal fun CharsetEncoder.encodeToImpl(
    destination: Sink,
    input: CharSequence,
    fromIndex: Int,
    toIndex: Int
) {
    var start = fromIndex
    if (start >= toIndex) return

    while (true) {
        val rc = encodeImpl(input, start, toIndex, destination)
        check(rc >= 0)
        start += rc

        when {
            start >= toIndex -> break
        }
    }
}
