private fun Char.shouldEscape(): Boolean = this.code.let { codepoint ->
    when (codepoint) {
        // the only forbidden character is backslash
        in 0x3f..0x7e -> codepoint == 0x5c

        // minus, point, slash (allowed), digits + colon :
        in 0x2d..0x3a -> false

        // $%&'()*
        in 0x24..0x2a -> false

        // exclamation
        0x21 -> false

        else -> true
    }
}
```

