internal fun findSpaceOrEnd(text: CharSequence, range: MutableRange): Int {
    var idx = range.start
    val end = range.end

    if (idx >= end || text[idx].isWhitespace()) return idx
    idx++

    while (idx < end) {
        if (text[idx].isWhitespace()) return idx
        idx++
    }

    return idx
}
