private suspend fun OidcProvider.refreshSession(
    token: OidcToken.Id,
    now: Instant,
    refresh: suspend () -> OidcToken.Id?
): OidcToken.Id? {
    val newToken = try {
        refresh()
    } catch (cause: OidcTokenRejectedException) {
        // The provider answered, but with a token that cannot be trusted.
        logger.debug("OpenID Connect session refresh returned an invalid token: {}", cause.message)
        clearOidcSession()
        return null
    } catch (cause: Exception) {
        clearSessionIfExpired(token, now)
        throw cause
    }
    return newToken ?: run {
        logger.debug("OpenID Connect session refresh did not return an ID token.")
        clearSessionIfExpired(token, now)
    }
}
