): Map<KParameter, Any?> =
    parameters.mapNotNull { parameter ->
        parameter to try {
            resolve(parameter)
        } catch (cause: Exception) {
            when {
                // ignore
                parameter.isOptional -> return@mapNotNull null

                // let value = null
                parameter.type.isMarkedNullable -> null

                else -> throw cause
            }
        }
    }.toMap()
