internal fun calculateMultipleRangesBodyLength(
    ranges: List<LongRange>,
    fullLength: Long?,
    boundary: String,
    contentType: String
): Long {
    // header length + range size + newline
    val contentLength = ranges.sumOf {
        calculateHeadersLength(
            it,
            boundary,
            contentType,
            fullLength
        ) + it.last - it.first + 3L
    }
    // -- + boundary + -- + newline
    return contentLength + boundary.length + 6
}
```

