    if (entryCount == 0) return null
    val hash = computeHash(name)
    var idx = hashBuckets[hash and (hashBuckets.size - 1)]
    while (idx >= 0) {
        if (keyStorage[idx].equals(name, caseInsensitiveName)) {
            return valueStorage[idx]
        }
        idx = hashNext[idx]
    }
    return null
