private suspend fun proceedLoop(): TSubject {
    do {
        val index = index
        if (index == -1) {
            break
        }
        val interceptors = interceptors
        if (index >= interceptors.size) {
            finish()
            break
        }
        val executeInterceptor = interceptors[index]
        this.index = index + 1
        executeInterceptor.invoke(this, subject)
    } while (true)

    return subject
}
