private fun MutableList<String>.processAndReplaceComponent(component: String) {
    if (component.isEmpty() ||
        component == "." ||
        component == "~" ||
        component.toUpperCasePreservingASCIIRules() in ReservedWords
    ) {
        return
    }
    if (component == "..") {
        if (isNotEmpty()) {
            removeAt(lastIndex)
        }
        return
    }

    component.filter { it >= ' ' && it !in ReservedCharacters }
        .trimEnd { it == ' ' || it == '.' }
        .takeIf { it.isNotEmpty() }?.let { filtered ->
            add(filtered)
        }
}
