            host,
            sslPort,
            sslKeyStorePath,
            sslKeyStorePassword,
            sslPrivateKeyPassword,
            sslKeyAlias,
            sslTrustStorePath,
            sslTrustStorePassword,
            sslEnabledProtocols
        )
    }

    return CommandLineConfig(applicationProperties, engineConfig)
}
