        is BinaryFormat -> {
            if (content is Frame.Binary) {
                format.decodeFromByteArray(serializer, content.readBytes())
            } else {
                throw WebsocketDeserializeException(
                    "Unsupported format $format for ${content.frameType.name}",
                    frame = content
                )
            }
        }

        else -> {
            error("Unsupported format $format")
