public fun close() {
    try {
        curRef.loop { cur ->
            if (cur.close()) return // closed this copy
            curRef.compareAndSet(cur, cur.next()) // move to next
        }
    } finally {
        if (!closed.compareAndSet(0, 1)) return
    }
}
