internal fun skipSpaces(text: CharSequence, range: MutableRange) {
    var idx = range.start
    val end = range.end

    if (idx >= end || !text[idx].isWhitespace()) return
    idx++

    while (idx < end) {
        if (!text[idx].isWhitespace()) break
        idx++
    }

    range.start = idx
}
