      if (message is DataMessage) {
        windowHandler.gotData(message.bytes.length);
      }
      _pendingMessages.add(message);
      if (message.endStream) startClosing();

      _tryDispatch();
      _tryUpdateBufferIndicator();
    }
  });
}
