func run(identifier: String) {
    measure(identifier: identifier) {
        let group = MultiThreadedEventLoopGroup(numberOfThreads: 1)
        let loop = group.next()
        let counter = try! loop.submit { () -> Int in
            var counter: Int = 0

            for _ in 0..<10000 {
                _ = loop.submit {
                    counter &+= 1
                    return counter
                }
            }

            return counter
        }.wait()

        try! group.syncShutdownGracefully()
        return counter
    }
}
