func subtreeWidths(rootIndex: Int) -> (Int, Int) {
    let lcIdx = self.leftIndex(rootIndex)
    let rcIdx = self.rightIndex(rootIndex)
    var leftSpace = 0
    var rightSpace = 0
    if lcIdx < self._storage.count {
