func _finishSource(with error: Error? = nil, context: ChannelHandlerContext) {
    guard let source = self.source else {
        return
    }

    // We need to deliver the reads first to buffer them in the source.
    self._deliverReads(context: context)

    if let error = error {
        source.finish(error)
    } else {
        source.finish()
    }

