private func validateHeaderLength(_ newLength: Int) -> CInt {
    self.currentFieldByteLength += newLength
    if self.currentFieldByteLength > self.maximumHeaderFieldSize {
        self.richerError = HTTPParserError.headerOverflow
        return -1
