public func write(context: ChannelHandlerContext, data: NIOAny, promise: EventLoopPromise<Void>?) {
    switch self.state {
    case .notInChannelYet:
        preconditionFailure("MessageToByteHandler.write called before it was added to a Channel")
    case .error(let error):
        promise?.fail(error)
        context.fireErrorCaught(error)
        return
    case .done:
        // let's just ignore this
        return
    case .operational:
        // there's actually some work to do here
        break
    }
    let data = MessageToByteHandler.unwrapOutboundIn(data)

    do {
        self.buffer!.clear()
        try self.encoder.encode(data: data, out: &self.buffer!)
        context.write(MessageToByteHandler.wrapOutboundOut(self.buffer!), promise: promise)
    } catch {
        self.state = .error(error)
        promise?.fail(error)
        context.fireErrorCaught(error)
    }
}
```

