func run() -> Int {
    let counter = try! self.loop.submit { [dg, loop, numTasks] in
        var counter: Int = 0
        for _ in 0..<numTasks {
            dg!.enter()

            loop!.assumeIsolatedUnsafeUnchecked().scheduleTask(in: .nanoseconds(0)) {
                counter &+= 1
                dg!.leave()
            }
        }
        return counter
    }.wait()
    self.dg.wait()

    return counter
}
