private func contextForPredicate0(_ body: (ChannelHandlerContext) -> Bool) -> ChannelHandlerContext? {
    var curCtx: ChannelHandlerContext? = self.head?.next
    while let context = curCtx, context !== self.tail {
        if body(context) {
            return context
        }
        curCtx = context.next
    }

    return nil
}
