static func getLocalContextID(_ socketFD: NIOBSDSocket.Handle) throws -> Self {
    #if canImport(Darwin)
    let request = CNIODarwin_IOCTL_VM_SOCKETS_GET_LOCAL_CID
    let fd = socketFD
    #elseif os(Linux) || os(Android)
