                        // EPERM in containers.
                        _ = sys_pthread_setname_np(hThread.handle, namePtr)
                    }
                }

                body(NIOThread(handle: hThread, desiredName: name))

                #if os(Android)
                return UnsafeMutableRawPointer(bitPattern: 0xdeadbee)!
                #else
                return nil
                #endif
            },
            args: argv0
        )
    }
    precondition(res == 0, "Unable to create thread: \(res)")
}
