                        FileSystemError.read(
                            usingSyscall: .pread,
                            error: error,
                            path: sendableView.path,
                            location: .here()
                        )
                    )
                }
            }
            .get()
        } onUnavailable: {
            FileSystemError(
                code: .closed,
