mutating func unbuffer() -> UnbufferAction {
    switch self.state {
    case .initial, .awaitingUpgrader, .upgraderReady, .upgrading, .finished:
        preconditionFailure("Invalid state \(self.state)")

    case .unbuffering(var unbuffering):
        self.state = .modifying

