func removeHandlers() {
    self.eventLoop.assertInEventLoop()

    if let head = self.head {
        while let context = head.next {
            removeHandlerFromPipeline(context: context, promise: nil)
        }
        removeHandlerFromPipeline(context: self.head!, promise: nil)
    }
    self.head = nil
    self.tail = nil

    self.destroyed = true
    self._channel = nil
}
