func _readFromBuffer<T>(buffer: inout CircularBuffer<NIOAny>) throws -> T? {
    self.embeddedEventLoop.checkCorrectThread()
    if buffer.isEmpty {
        return nil
    }
    let elem = buffer.removeFirst()
    guard let t = self._channelCore.tryUnwrapData(elem, as: T.self) else {
