func truncated(to maxLength: Int, continuation: String = "...") -> String {
    let length = self.count

    if length <= maxLength {
        return self
    }

    let toRemove = (length - maxLength) + continuation.count

    var copy = self
    copy.removeLast(toRemove)
    copy.append(contentsOf: continuation)

    return copy
}
