private func _shutdownGracefully(queue: DispatchQueue, _ callback: @escaping @Sendable (Error?) -> Void) {
    guard self.canBeStopped else {
        queue.async {
            callback(NIOThreadPoolError.UnsupportedOperation())
        }
        return
    }

    let threadsToJoin = self._workAvailable.withLockSettingWorkAvailable {
        switch self._state {
        case .running(let items):
            self._state = .modifying
            queue.async {
                for item in items {
                    item.workItem(.cancelled)
                }
            }
            self._state = .shuttingDown(Array(repeating: true, count: self.numberOfThreads))

            let threads = self.threads!
            self.threads = nil

            // Wake all threads so they can see .shuttingDown and exit.
            return (workAvailable: self.numberOfThreads, signal: .broadcastAll, result: threads)

        case .shuttingDown, .stopped:
            // Don't modify workAvailable - threads may still be waking up to see .shuttingDown
            return (workAvailable: nil, signal: .none, result: [])

        case .modifying:
            fatalError(".modifying state misuse")
        }
    }

    DispatchQueue(label: "io.swiftnio.NIOThreadPool.shutdownGracefully").async {
        for thread in threadsToJoin {
            thread.join()
        }
        queue.async {
            callback(nil)
        }
    }
}
```

