internal func syscall(
    where function: String = #function,
    _ body: () throws -> OpaquePointer?
)
    throws -> OpaquePointer
{
    while true {
        if let res = try body() {
            return res
        } else {
            let err = errno
            switch err {
            case EINTR:
                continue
            default:
                preconditionIsNotUnacceptableErrno(err: err, where: function)
                throw IOError(errnoCode: err, reason: function)
            }
        }
    }
}
```

