  StringBuilder builder = new StringBuilder(method.getName());
  builder.append('(');

  String sep = "";
  for (Class<?> paramType : method.getParameterTypes()) {
    builder.append(sep).append(paramType.getName());
    sep = ",";
  }

  builder.append(')');
  return builder.toString();
}
