    $id = trim($id) ?: "'".(string) Str::uuid()."'";

    return '<?php if (! $__env->hasRenderedOnce('.$id.')): $__env->markAsRenderedOnce('.$id.');
$__env->startPush('.$stack.'); ?>';
}
