public static function range($from, $to, $step = 1, ...$args)
{
    if ($step == 0) {
        throw new InvalidArgumentException('Step value cannot be zero.');
    }

    return new static(function () use ($from, $to, $step) {
        if ($from <= $to) {
            for (; $from <= $to; $from += abs($step)) {
                yield $from;
            }
        } else {
            for (; $from >= $to; $from -= abs($step)) {
                yield $from;
            }
        }
    });
}
```

