public function filter(?callable $callback = null)
{
    if (is_null($callback)) {
        $callback = fn ($value) => (bool) $value;
    }

    return new static(function () use ($callback) {
        foreach ($this as $key => $value) {
            if ($callback($value, $key)) {
                yield $key => $value;
            }
        }
    });
}
